package fraymus.workspace;
import org.junit.Test;import static org.junit.Assert.*;import org.json.*;import java.util.*;
public class GameBudgetPolicy124Test {
 static JSONObject sample(String strategy,double seconds,int pickups){return new JSONObject().put("id",UUID.randomUUID().toString()).put("strategy",strategy).put("seconds",seconds).put("pickups",pickups).put("safe",true).put("renderer","fixture");}
 static JSONArray evidence(){var a=new JSONArray();for(int i=0;i<3;i++){a.put(sample("direct",10+i*.1,0));a.put(sample("full",15+i*.1,1));}return a;}
 @Test public void allowanceCoversVariationAndVerification(){var a=evidence();assertEquals("direct",GameBudgetPolicy124.choose(a,4,1).getString("selected"));var b=GameBudgetPolicy124.choose(a,10,1);assertEquals("full",b.getString("selected"));var x=b.getJSONArray("alternatives").getJSONObject(2);assertEquals(6.85,x.getDouble("requiredSecondsPerPickup"),.00001);assertEquals("direct",GameBudgetPolicy124.choose(a,10,6).getString("selected"));assertEquals("direct",GameBudgetPolicy124.choose(a,0,0).getString("selected"));}
 @Test public void unknownMixedBenefitFailuresAndTimingVariationAbstain(){assertEquals("direct",GameBudgetPolicy124.choose(new JSONArray(),120,0).getString("selected"));for(String condition:List.of("benefit","failure","renderer","timing")){var a=evidence();var s=a.getJSONObject(1);switch(condition){case "benefit"->s.put("pickups",0);case "failure"->s.put("safe",false);case "renderer"->s.put("renderer","other");case "timing"->s.put("seconds",30);}assertEquals(condition,"direct",GameBudgetPolicy124.choose(a,120,0).getString("selected"));}}
 @Test public void cheaperVerifiedAlternativeWinsAndIncompleteDoesNot(){var a=evidence();for(int i=0;i<2;i++)a.put(sample("no-return",12,1));assertEquals("full",GameBudgetPolicy124.choose(a,10,0).getString("selected"));a.put(sample("no-return",12,1));assertEquals("no-return",GameBudgetPolicy124.choose(a,10,0).getString("selected"));}
 @Test public void invalidAndDuplicateSamplesCannotEnter(){var a=evidence();a.put(a.getJSONObject(0));assertThrows(IllegalArgumentException.class,()->GameBudgetPolicy124.choose(a,10,0));for(double n:new double[]{-1,Double.NaN,Double.POSITIVE_INFINITY,121})assertThrows(IllegalArgumentException.class,()->GameBudgetPolicy124.choose(evidence(),n,0));var b=evidence();b.getJSONObject(1).put("pickups",.5);assertThrows(IllegalArgumentException.class,()->GameBudgetPolicy124.choose(b,10,0));}
 @Test public void explicitBudgetIsRequiredAndOldDefaultsRemain(){String r="Create a playable Mario level goombaTile=24 ";assertFalse(GameBudgetPolicy124.request(r).getBoolean("budgeted"));assertEquals(4,GameBudgetPolicy124.request(r+"pickupStrategy=budget pickupBudgetSeconds=4.").getDouble("allowance"),0);for(String x:List.of("pickupStrategy=budget","pickupBudgetSeconds=4","pickupStrategy=budget pickupBudgetSeconds=NaN","pickupStrategy=budget pickupBudgetSeconds=Infinity","pickupStrategy=budget pickupBudgetSeconds=-1","pickupStrategy=budget pickupBudgetSeconds=121","pickupStrategy=budget pickupBudgetSeconds=4 pickupBudgetSeconds=6","pickupStrategy=budget pickupBudgetSeconds=4 pickupStrategy=full"))assertThrows(x,IllegalArgumentException.class,()->GameBudgetPolicy124.request(r+x));assertThrows(IllegalArgumentException.class,()->GameBudgetPolicy124.request("Create a playable Mario level pickupStrategy=budget pickupBudgetSeconds=3"));}
 @Test public void allDeclaredCoursesPassAdmission(){for(String partition:List.of("development","reserved"))for(String c:GameBudgetStudy124Test.cases(partition).values())GameBudgetPolicy124.request("Create a playable Mario level "+c+" pickupStrategy=budget pickupBudgetSeconds=30");}
}
